<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> logs (msg, created_at) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;test&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NOW</span><span style="color:#ABB2BF;">());</span></span>
