<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> salary </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 16500</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
